do $$begin if current_setting('server_version_num')::integer<150000 then raise exception 'PostgreSQL 15+ obrigatório';end if;if to_regprocedure('erp_security.current_aal()')is null or to_regprocedure('erp_security.has_permission(uuid,text)')is null or to_regclass('public.erp_establishments')is null then raise exception 'M02/M04 ausente';end if;if to_regclass('public.erp_agent_installations')is not null or to_regprocedure('public.erp_activate_agent_pairing(uuid,text,text,text,text,text)')is not null then raise exception 'Objetos M12 já existem sem histórico 0029';end if;if exists(select 1 from public.erp_permissions where key in('agent.read','agent.manage','peripheral.manage','offline.sync','agent.audit')and category<>'Agente local')then raise exception 'Colisão de permissões M12';end if;end$$;
select now()checked_at,'M12_PREFLIGHT_OK'result;
